import mido
from collections import Counter, defaultdict, deque
import statistics

GM = ('Acoustic Grand Piano,Bright Acoustic Piano,Electric Grand Piano,Honky-tonk Piano,Electric Piano 1,Electric Piano 2,Harpsichord,Clavinet,Celesta,Glockenspiel,Music Box,Vibraphone,Marimba,Xylophone,Tubular Bells,Dulcimer,Drawbar Organ,Percussive Organ,Rock Organ,Church Organ,Reed Organ,Accordion,Harmonica,Tango Accordion,Acoustic Guitar nylon,Acoustic Guitar steel,Electric Guitar jazz,Electric Guitar clean,Electric Guitar muted,Overdriven Guitar,Distortion Guitar,Guitar harmonics,Acoustic Bass,Electric Bass finger,Electric Bass pick,Fretless Bass,Slap Bass 1,Slap Bass 2,Synth Bass 1,Synth Bass 2,Violin,Viola,Cello,Contrabass,Tremolo Strings,Pizzicato Strings,Orchestral Harp,Timpani,String Ensemble 1,String Ensemble 2,Synth Strings 1,Synth Strings 2,Choir Aahs,Voice Oohs,Synth Voice,Orchestra Hit,Trumpet,Trombone,Tuba,Muted Trumpet,French Horn,Brass Section,Synth Brass 1,Synth Brass 2,Soprano Sax,Alto Sax,Tenor Sax,Baritone Sax,Oboe,English Horn,Bassoon,Clarinet,Piccolo,Flute,Recorder,Pan Flute,Blown Bottle,Shakuhachi,Whistle,Ocarina,Lead square,Lead sawtooth,Lead calliope,Lead chiff,Lead charang,Lead voice,Lead fifths,Lead bass and lead,Pad new age,Pad warm,Pad polysynth,Pad choir,Pad bowed,Pad metallic,Pad halo,Pad sweep,FX rain,FX soundtrack,FX crystal,FX atmosphere,FX brightness,FX goblins,FX echoes,FX sci-fi,Sitar,Banjo,Shamisen,Koto,Kalimba,Bag pipe,Fiddle,Shanai,Tinkle Bell,Agogo,Steel Drums,Woodblock,Taiko Drum,Melodic Tom,Synth Drum,Reverse Cymbal,Guitar Fret Noise,Breath Noise,Seashore,Bird Tweet,Telephone Ring,Helicopter,Applause,Gunshot').split(',')
PC = ['C','C#','D','Eb','E','F','F#','G','Ab','A','Bb','B']
DRUM = {35:'acoustic bass drum',36:'bass drum',37:'side stick',38:'snare',39:'hand clap',40:'electric snare',41:'low floor tom',42:'closed hi-hat',43:'high floor tom',44:'pedal hi-hat',45:'low tom',46:'open hi-hat',47:'low-mid tom',48:'high-mid tom',49:'crash cymbal',50:'high tom',51:'ride cymbal',52:'Chinese cymbal',53:'ride bell',54:'tambourine',55:'splash cymbal',56:'cowbell',57:'crash cymbal 2',59:'ride cymbal 2'}

def note(n):
    return PC[n % 12] + str(n // 12 - 1)

def adapt(path):
    mid = mido.MidiFile(path, clip=True)
    ppq = mid.ticks_per_beat
    lines = ['MIDI type %s, %d tracks, %d ticks per quarter note.' % (mid.type, len(mid.tracks), ppq)]
    if ppq <= 0:
        return {'text': '\n'.join(lines + ['SMPTE timing; detailed beat analysis unavailable.'])}
    events, meta, tempos, meters = [], [], [], []
    track_names = {}
    end = 0
    for ti, track in enumerate(mid.tracks):
        t = 0
        for msg in track:
            t += msg.time
            if msg.is_meta:
                if msg.type == 'set_tempo': tempos.append((t, msg.tempo))
                elif msg.type == 'time_signature': meters.append((t, msg.numerator, msg.denominator))
                elif msg.type in ('track_name','instrument_name','text','lyrics','marker','copyright','key_signature'):
                    val = getattr(msg, 'text', getattr(msg, 'name', getattr(msg, 'key', '')))
                    if val:
                        val = str(val).replace('\n',' ')[:160]
                        meta.append((ti, t, msg.type, val))
                        if msg.type == 'track_name': track_names[ti] = val
            elif hasattr(msg, 'channel'):
                events.append((t, ti, len(events), msg))
        end = max(end, t)
    events.sort(key=lambda x: (x[0], x[1], x[2]))
    tempos.sort(); meters.sort()
    if tempos:
        lines.append('Tempo events: ' + '; '.join('beat %.2f: %.1f BPM' % (t/ppq, 60000000/v) for t,v in tempos[:12] if v > 0))
    else: lines.append('No tempo event; MIDI default 120 BPM.')
    if meters:
        lines.append('Meter events: ' + '; '.join('beat %.2f: %d/%d' % (t/ppq,n,d) for t,n,d in meters[:10]))
    else: lines.append('No meter event; MIDI default 4/4.')
    tempo_map = [(0,500000)] + tempos
    seconds = 0.0
    for i,(t,v) in enumerate(tempo_map):
        nxt = tempo_map[i+1][0] if i+1 < len(tempo_map) else end
        if nxt > t: seconds += (nxt-t)*v/(ppq*1000000)
    lines.append('Length: %.1f quarter-note beats, approximately %.1f seconds.' % (end/ppq, seconds))
    if meta:
        lines.append('Embedded metadata: ' + '; '.join('track %d beat %.1f %s: %s' % (ti+1,t/ppq,k,v) for ti,t,k,v in meta[:18]))
    programs = defaultdict(Counter)
    current = defaultdict(int)
    notes = defaultdict(list)
    active = defaultdict(deque)
    controls = defaultdict(Counter)
    for t,ti,_,msg in events:
        ch = msg.channel
        if msg.type == 'program_change': current[ch] = msg.program
        elif msg.type == 'control_change': controls[ch][msg.control] += 1
        elif msg.type == 'note_on' and msg.velocity > 0:
            rec = [t, None, msg.note, msg.velocity, ti, current[ch]]
            notes[ch].append(rec); active[(ch,msg.note)].append(rec)
            programs[ch][current[ch]] += 1
        elif msg.type == 'note_off' or (msg.type == 'note_on' and msg.velocity == 0):
            q = active[(ch,msg.note)]
            if q: q.popleft()[1] = t
    total = sum(map(len, notes.values()))
    lines.append('Total note attacks: %d; active channels: %d.' % (total,len(notes)))
    allpc = Counter()
    for ch, ns in sorted(notes.items(), key=lambda x: -len(x[1])):
        if ch != 9:
            allpc.update(n[2] % 12 for n in ns)
    if allpc:
        lines.append('Pitched note-class counts: ' + ', '.join('%s %d' % (PC[p],c) for p,c in allpc.most_common()))
    for ch, ns in sorted(notes.items(), key=lambda x: -len(x[1]))[:12]:
        pitches = [n[2] for n in ns]; velocities = [n[3] for n in ns]
        tracks = sorted(set(n[4]+1 for n in ns))
        if ch == 9:
            inst = 'percussion channel; ' + ', '.join('%s %d' % (DRUM.get(p,'drum '+str(p)),c) for p,c in Counter(pitches).most_common(8))
        else:
            inst = ', '.join('%s (%d notes)' % (GM[p] if 0 <= p < 128 else str(p),c) for p,c in programs[ch].most_common(4))
        starts = sorted(set(n[0] for n in ns))
        gaps = [(b-a)/ppq for a,b in zip(starts,starts[1:]) if b>a]
        durations = [(n[1]-n[0])/ppq for n in ns if n[1] is not None and n[1]>=n[0]]
        simultaneous = Counter(n[0] for n in ns)
        poly = sum(c for c in simultaneous.values() if c>1)/len(ns)
        desc = 'Channel %d, tracks %s: %s; %d notes, range %s-%s, velocity median %d (range %d-%d), %.0f%% of notes in simultaneous attacks' % (ch+1, ','.join(map(str,tracks)), inst, len(ns), note(min(pitches)), note(max(pitches)), statistics.median(velocities), min(velocities), max(velocities), 100*poly)
        if durations: desc += '; median duration %.2f beats' % statistics.median(durations)
        if gaps:
            common = Counter(round(g,2) for g in gaps).most_common(3)
            desc += '; common onset gaps ' + ', '.join('%.2f beats (%d)' % x for x in common)
        lines.append(desc + '.')
        if ch != 9:
            seq = sorted(ns, key=lambda n:(n[0],n[2]))[:24]
            lines.append('  Opening attacks (beat:note): ' + ' '.join('%.2f:%s' % (n[0]/ppq,note(n[2])) for n in seq))
        if controls[ch]:
            lines.append('  MIDI controllers used: ' + ', '.join('%d (%d)' % x for x in controls[ch].most_common(5)))
    pitched = [n for ch,ns in notes.items() if ch != 9 for n in ns]
    if pitched:
        groups = defaultdict(list)
        for n in pitched: groups[n[0]].append(n[2])
        chords = []
        for t, ps in sorted(groups.items()):
            pcs = sorted(set(p % 12 for p in ps))
            if len(pcs) >= 3:
                chords.append('%.1f:%s' % (t/ppq,'/'.join(PC[p] for p in pcs)))
        if chords: lines.append('Simultaneous pitch-class groups at attacks (beat:classes): ' + ' '.join(chords[:16]))
    return {'text': '\n'.join(lines)[:4000]}
